def mdc(a, b):
    if b == 0:
        return a
    return mdc(b, a % b)

def mmc(a, b):
    return abs(a * b) // mdc(a, b)

print(f"MMC(12, 18) = {mmc(12, 18)}")  # 36
print(f"MMC(5, 7) = {mmc(5, 7)}")      # 35

def fibonacci_iterativo(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

print(f"Fibonacci(8) = {fibonacci_iterativo(8)}")    # 21
print(f"Fibonacci(35) = {fibonacci_iterativo(35)}")  # 9227465 (Execução instantânea O(n))
